def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_history_is_newest_first_with_status_and_discounted_totals(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]          # 2_500, no discount
    second = order(shop, "c1", ("LAMP", 2)).body["order_id"]         # 12_000, 10% off
    third = order(shop, "c1", ("PEN", 1)).body["order_id"]           # 300, cancelled below
    shop.orders.handle_cancel(third)
    # Another customer's order must not appear.
    order(shop, "c2", ("BOOK", 1))

    response = shop.insights.handle_order_history("c1")

    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": [
        {"order_id": third, "status": "cancelled", "total_cents": 300},
        {"order_id": second, "status": "placed", "total_cents": 10_800},
        {"order_id": first, "status": "placed", "total_cents": 2_500},
    ]}


def test_totals_match_order_summary(shop):
    created = order(shop, "c2", ("LAMP", 2), ("BOOK", 4)).body["order_id"]  # gold: 15% off
    history = shop.insights.handle_order_history("c2").body["orders"]
    summary = shop.orders.handle_get(created).body
    assert history == [{"order_id": created, "status": "placed",
                        "total_cents": summary["total_cents"]}]

